scripts.count_inversions:
def solve(inputs: dict) -> float:
    values = inputs['VALUES']
    count = 0

    # Count all pairs where an earlier entry exceeds a later entry
    for i in range(len(values)):
        for j in range(i + 1, len(values)):
            if values[i] > values[j]:
                count += 1

    return float(count)

