{"name": "factorial_mod", "code": "import math

def solve(inputs: dict) -> float:
    n = inputs['N']
    mod = inputs['MOD']

    # Calculate factorial
    factorial = math.factorial(n)

    # Apply modulo
    result = factorial % mod

    return float(result)
